"""Generate committed rule catalog from the central registry. Run from repository root."""
from pathlib import Path
from argus.analysis.rules import REGISTRY


def render(category):
    out = ['# ' + category.capitalize() + ' rule catalog', '',
           'Generated by `uv run python tools/generate_rule_docs.py` from `argus.analysis.rules.REGISTRY`.', '',
           'Findings are static heuristic indicators, not confirmed defects. Exact syntactic or graph scope, confidence and limitations are defined per rule.', '']
    for r in REGISTRY:
        if r.category.value != category:
            continue
        out += ['## ' + r.id + ' — ' + r.name, '',
                f'- Version: {r.version}; implementation status: {r.status}.',
                f'- Primary category: {r.category.value}; secondary categories: {", ".join(r.secondary_categories) or "none"}.',
                f'- Languages: {", ".join(r.languages)}.',
                f'- Required capabilities: {", ".join(r.capabilities)}.',
                f'- Evaluated parameter: `{r.parameter}`; default threshold: `{r.default}`; strict greater-than.',
                f'- Methodology: {r.methodology}',
                f'- Contextual investigation: {r.contextual_analysis}',
                f'- Contextual tests: `{r.contextual_tests}`.' if r.contextual_tests else '- Contextual tests: not applicable.',
                f'- Default severity: {r.severity}; confidence criteria: {r.confidence}.',
                f'- Why it matters: {r.rationale}',
                f'- Positive example: {r.positive}.', f'- Negative example: {r.negative}.',
                f'- Remediation: {r.remediation}', f'- Validation: {r.validation}',
                f'- Limitations and false positives: {r.limitations}',
                f'- Associated automated tests: `{r.tests}` (parameterized positive, negative and disabled cases); `tests/test_analysis_graphs.py` and `tests/test_analysis_parsing.py` cover measurement primitives.', '']
    return '\n'.join(out)


def generate():
    root = Path('docs/rules')
    return {root / (category + '.md'):render(category) for category in tuple(dict.fromkeys(r.category.value for r in REGISTRY))}

if __name__ == '__main__':
    for path, text in generate().items():
        path.write_text(text)
